import json, struct, zlib, random, subprocess, sys

# ---------- independent two-pass reference ----------
def reference(request):
    pages = [bytearray(bytes.fromhex(p)) for p in request["pages"]]
    checkpoint = request["checkpoint"]
    log = bytes.fromhex(request["log"]) if request["log"] else b""
    n, pos, last_seq = len(log), 0, 0
    records = []
    while pos < n:
        if n - pos < 13:
            break
        plen, seq, kind, txid = struct.unpack_from("<IIBI", log, pos)
        if plen > 4096:
            break
        end = pos + 13 + plen + 4
        if end > n:
            break
        payload = log[pos + 13: pos + 13 + plen]
        (crc_stored,) = struct.unpack_from("<I", log, pos + 13 + plen)
        if zlib.crc32(log[pos:pos + 13 + plen]) & 0xFFFFFFFF != crc_stored:
            break
        if seq == 0 or seq <= last_seq or txid == 0:
            break
        if kind in (1, 4):
            if plen != 0:
                break
        elif kind == 2:
            if plen < 6:
                break
            pi, off, cnt = struct.unpack_from("<HHH", payload, 0)
            if cnt == 0 or plen != 6 + cnt:
                break
            if pi >= len(pages) or off + cnt > len(pages[pi]):
                break
        elif kind == 3:
            if plen != 8:
                break
        else:
            break
        records.append((seq, kind, txid, payload))
        pos = end
        last_seq = seq

    # second pass: transaction semantics, collecting sealed commits
    active = {}  # txid -> list of payloads
    commits = []  # (seq, [payloads])
    for seq, kind, txid, payload in records:
        if kind == 1:
            active[txid] = []
        elif kind == 2:
            if txid in active:
                active[txid].append(payload)
        elif kind == 4:
            active.pop(txid, None)
        else:
            staged = active.pop(txid, None)
            if staged is not None:
                cnt, dg = struct.unpack("<II", payload)
                if cnt == len(staged) and dg == (zlib.crc32(b"".join(staged)) & 0xFFFFFFFF):
                    commits.append((seq, staged))
    for seq, staged in commits:
        if seq > checkpoint:
            for payload in staged:
                pi, off, cnt = struct.unpack_from("<HHH", payload, 0)
                pages[pi][off:off + cnt] = payload[6:]
    return {"pages": [p.hex() for p in pages], "valid_bytes": pos, "last_seq": last_seq}

# ---------- generator ----------
def rec(seq, kind, txid, payload=b""):
    hdr = struct.pack("<IIBI", len(payload), seq, kind, txid)
    return hdr + payload + struct.pack("<I", zlib.crc32(hdr + payload) & 0xffffffff)

def pp(page, off, data):
    return struct.pack("<HHH", page, off, len(data)) + data

def gen(rng):
    n_pages = rng.randint(1, 8)
    plen_page = rng.randint(1, 64)
    pages = [bytes(rng.randbytes(plen_page)).hex() for _ in range(n_pages)]
    records = []
    seq = 0
    active = set()
    n_rec = rng.randint(0, 30)
    for _ in range(n_rec):
        seq += rng.randint(1, 5)
        if rng.random() < 0.03:
            seq = rng.choice([1, 2**32 - 1, 2**31])
            if records:
                prev = records[-1][0]
                if seq <= prev:
                    seq = prev + 1
        kind = rng.choice([1, 2, 2, 2, 3, 3, 4])
        txid = rng.choice([1, 1, 2, 2, 3, 4, 2**32 - 1])
        if kind == 1:
            payload = b""
            active.add(txid)
        elif kind == 2:
            pi = rng.randrange(n_pages)
            off = rng.randrange(plen_page)
            cnt = rng.randint(1, plen_page - off)
            payload = pp(pi, off, rng.randbytes(cnt))
        elif kind == 3:
            payload = struct.pack("<II", 0, 0)  # fixed later if sealing
        else:
            payload = b""
        records.append([seq, kind, txid, payload])
    # second pass to compute proper commit seals with probability
    staged = {}
    for r in records:
        seq, kind, txid, payload = r
        if kind == 1:
            staged[txid] = []
        elif kind == 2 and txid in staged:
            staged[txid].append(payload)
        elif kind == 4:
            staged.pop(txid, None)
        elif kind == 3:
            st = staged.pop(txid, None)
            if st is not None and rng.random() < 0.8:
                dg = zlib.crc32(b"".join(st)) & 0xffffffff
                cnt = len(st)
                if rng.random() < 0.15:  # corrupt seal sometimes
                    if rng.random() < 0.5:
                        dg ^= rng.getrandbits(32)
                    else:
                        cnt += rng.choice([1, 2])
                r[3] = struct.pack("<II", cnt, dg)
            else:
                r[3] = struct.pack("<II", rng.getrandbits(8), rng.getrandbits(32))
    log = b"".join(rec(*r) for r in records)
    # inject corruption / tearing
    corrupt = rng.random()
    if corrupt < 0.25 and log:
        cut = rng.randrange(len(log) + 1)
        log = log[:cut]  # torn
    elif corrupt < 0.45 and log:
        log = bytearray(log)
        pos = rng.randrange(len(log))
        log[pos] ^= 1 << rng.randrange(8)  # bit flip anywhere
        log = bytes(log)
    elif corrupt < 0.55 and log:
        log = log + rng.randbytes(rng.randint(1, 20))  # trailing junk
    max_seq = max([r[0] for r in records], default=0)
    checkpoint = rng.choice([0, 1, rng.randint(0, max_seq + 3), max_seq, max_seq + 2, 2**32 + 5])
    return {"pages": pages, "checkpoint": checkpoint, "log": log.hex()}

rng = random.Random(20241008)
