reqs = [gen(rng) for _ in range(CASES)]
inp = "".join(json.dumps(r) + "\n" for r in reqs)
p = subprocess.run([sys.executable, "/app/main.py"], input=inp, text=True,
                   capture_output=True, cwd="/app")
assert p.returncode == 0, p.stderr
lines = p.stdout.splitlines()
assert len(lines) == CASES, f"{len(lines)} vs {CASES}"
bad = 0
for i, (req, line) in enumerate(zip(reqs, lines)):
    got = json.loads(line)
    exp = reference(req)
    if got != exp:
        bad += 1
        if bad <= 3:
            print("MISMATCH", i)
            print(" req", json.dumps(req))
            print(" exp", exp)
            print(" got", got)
print("difftest:", "ALL MATCH" if not bad else f"{bad} MISMATCHES", f"({CASES} cases)")
